#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn gate_concurrent_manifest_renames_publish_one_destination() {
    use lance_namespace::models::{RenameTableRequest, TableExistsRequest};

    for attempt in 0..20 {
        let temp_dir = TempStdDir::default();
        let root = temp_dir.to_str().unwrap();
        let setup = DirectoryNamespaceBuilder::new(root).build().await.unwrap();

        let mut create_request = CreateTableRequest::new();
        create_request.id = Some(vec!["source".to_string()]);
        setup
            .create_table(
                create_request,
                Bytes::from(create_non_empty_test_ipc_data()),
            )
            .await
            .unwrap();

        let left = DirectoryNamespaceBuilder::new(root).build().await.unwrap();
        let right = DirectoryNamespaceBuilder::new(root).build().await.unwrap();
        let barrier = Arc::new(tokio::sync::Barrier::new(2));

        let left_barrier = barrier.clone();
        let left_rename = async {
            let mut request = RenameTableRequest::new("left".to_string());
            request.id = Some(vec!["source".to_string()]);
            left_barrier.wait().await;
            left.rename_table(request).await
        };
        let right_rename = async {
            let mut request = RenameTableRequest::new("right".to_string());
            request.id = Some(vec!["source".to_string()]);
            barrier.wait().await;
            right.rename_table(request).await
        };
        let (left_result, right_result) = tokio::join!(left_rename, right_rename);
        let successes = usize::from(left_result.is_ok()) + usize::from(right_result.is_ok());

        let observer = DirectoryNamespaceBuilder::new(root).build().await.unwrap();
        let mut exposed_destinations = 0;
        for name in ["left", "right"] {
            let mut request = TableExistsRequest::new();
            request.id = Some(vec![name.to_string()]);
            exposed_destinations += usize::from(observer.table_exists(request).await.is_ok());
        }

        assert_eq!(
            successes, 1,
            "attempt {attempt}: left={left_result:?}, right={right_result:?}"
        );
        assert_eq!(
            exposed_destinations, 1,
            "attempt {attempt}: one successful rename exposed {exposed_destinations} destinations; left={left_result:?}, right={right_result:?}"
        );
    }
}
```

